// Generated by Skyramp — UI test for the field-reorder save confirmation.
//
// Scenario: rapid-successive-field-reorders  (category: data_integrity)
//
// updateFields() in app/src/stores/fields.ts guards against out-of-order API responses
// with a `currentUpdate` token: a response is only merged into local state when its
// updateID is still the newest one. Two reorders issued back to back exercise that
// guard — the list, and the persisted order after a reload, must reflect the SECOND
// reorder, never the first.
import { test } from '@skyramp/skyramp';
import { expect } from '@playwright/test';
import {
	login,
	createCollection,
	dragField,
	fieldOrder,
	reloadDataModelPage,
	sortByField,
} from './skyramp_field_reorder_helpers';

const baseUrl = process.env.SKYRAMP_TEST_BASE_URL || 'http://localhost:8055';

test('back-to-back field reorders settle on the last requested order', async ({ page }) => {
	test.setTimeout(180000);
	page.setDefaultTimeout(15000);

	await login(page, baseUrl);
	const collection = await createCollection(page, baseUrl, 'qa_reorder_race');

	expect(await fieldOrder(page)).toEqual(['id', 'status', 'date_created']);

	const isFieldPatch = (r: { url(): string; request(): { method(): string } }) =>
		r.url().includes(`/fields/${collection}`) && r.request().method() === 'PATCH';

	// First reorder: status -> top.
	const firstSave = page.waitForResponse(isFieldPatch);
	await dragField(page, 1, 0);
	expect((await firstSave).status()).toBe(200);
	expect(await fieldOrder(page)).toEqual(['status', 'id', 'date_created']);

	// Second reorder, immediately after: date_created -> top.
	const secondSave = page.waitForResponse(isFieldPatch);
	await dragField(page, 2, 0);
	const secondResponse = await secondSave;
	expect(secondResponse.status()).toBe(200);

	// The last write must be the one that persisted: sort 1..3 in the second order.
	expect(sortByField(await secondResponse.json())).toEqual({ date_created: 1, status: 2, id: 3 });

	const expected = ['date_created', 'status', 'id'];
	expect(await fieldOrder(page)).toEqual(expected);

	// A stale first response must not win: re-read the persisted order.
	await reloadDataModelPage(page, baseUrl, collection);
	expect(await fieldOrder(page)).toEqual(expected);
});
